create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.paper_accounts (user_id uuid primary key references auth.users(id) on delete cascade, schema_version integer not null default 1, starting_virtual_usdc numeric not null default 10000 check (starting_virtual_usdc >= 0), available_virtual_usdc numeric not null default 10000 check (available_virtual_usdc >= 0), sol_quantity numeric not null default 0 check (sol_quantity >= 0), open_position_state text not null default 'FLAT' check (open_position_state in ('FLAT','LONG')), entry_price numeric, entry_timestamp timestamptz, entry_virtual_size numeric, realized_pnl numeric not null default 0, state_version bigint not null default 1, updated_at timestamptz not null default now());
create table if not exists public.paper_trades (user_id uuid not null references auth.users(id) on delete cascade, trade_id text not null, pair text not null default 'SOL/USDC', source text not null check (source in ('MANUAL','AUTONOMOUS')), strategy_id text, strategy_name text, automation_timeframe text, entry_timestamp timestamptz not null, entry_price numeric not null check (entry_price > 0), sol_quantity numeric not null check (sol_quantity >= 0), virtual_usdc_size numeric not null check (virtual_usdc_size >= 0), status text not null check (status in ('OPEN','CLOSED')), exit_timestamp timestamptz, exit_price numeric, realized_pnl numeric, pnl_percent numeric, exit_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (user_id, trade_id));
create table if not exists public.automation_preferences (user_id uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default false, strategy_id text not null default 'momentum', timeframe text not null default '15m', position_size_percent numeric not null default 10, processed_candle_ids jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.user_preferences (user_id uuid primary key references auth.users(id) on delete cascade, theme text not null default 'dark' check (theme in ('dark','light','system')), chart_timeframe text, chart_mode text, updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['profiles','paper_accounts','paper_trades','automation_preferences','user_preferences'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy "%s own select" on public.%I for select using (auth.uid() = %s)',t,t,case when t='profiles' then 'id' else 'user_id' end); execute format('create policy "%s own insert" on public.%I for insert with check (auth.uid() = %s)',t,t,case when t='profiles' then 'id' else 'user_id' end); execute format('create policy "%s own update" on public.%I for update using (auth.uid() = %s) with check (auth.uid() = %s)',t,t,case when t='profiles' then 'id' else 'user_id' end,case when t='profiles' then 'id' else 'user_id' end); execute format('create policy "%s own delete" on public.%I for delete using (auth.uid() = %s)',t,t,case when t='profiles' then 'id' else 'user_id' end); end loop; exception when duplicate_object then null; end $$;
